const char* cmd_espnow_deviceinfo(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  if (argWantsJson(argsInput)) {
    PSRAM_JSON_DOC(doc);
    doc["schema"]       = 1;
    // The stored name as ESP-NOW uses it: "" when none is set (ESP-NOW never
    // uses the fallback; Bluetooth and Wi-Fi do, see 'devicename').
    doc["name"]         = gSettings.espnowDeviceName;
    // False when no usable name is saved (empty, or one the name rule refuses),
    // the state 'devicename' shows as "HardwareOne-B2C3 (default)".
    doc["nameValid"]    = devicename::valid(gSettings.espnowDeviceName.c_str());
    // The same answer under the key every JSON reply with the name carries.
    doc["deviceNameSet"] = SelfDevice::deviceNameSet();
    doc["friendlyName"] = gSettings.espnowFriendlyName;
    doc["room"]         = gSettings.espnowRoom;
    doc["zone"]         = gSettings.espnowZone;
    doc["tags"]         = gSettings.espnowTags;
    doc["stationary"]   = gSettings.espnowStationary;
    const char* roleStr = "worker";
    if (gSettings.meshRole == MESH_ROLE_MASTER) roleStr = "master";
    else if (gSettings.meshRole == MESH_ROLE_BACKUP_MASTER) roleStr = "backup";
    doc["meshRole"] = roleStr;
    uint8_t myMac[6]; espnowSelfStaMac(myMac);
    doc["mac"] = String(MAC_STR(myMac));
    doc["hint"] = "this is THIS device's metadata - to list mesh peers use 'espnowdevices', or refresh one peer with 'espnowrequestmeta <peer>'";
    serializeJson(doc, getDebugBuffer(), 1024);
    return getDebugBuffer();
  }
  cliHint("this is THIS device's metadata - to list mesh peers use 'espnowdevices', or refresh one peer with 'espnowrequestmeta <peer>'");
  char* buf = getDebugBuffer();
  int pos = 0;
  pos += snprintf(buf + pos, 1024 - pos, "=== Device Metadata ===\n");
  {
    char shown[devicename::kDisplayCap];
    (void)SelfDevice::deviceNameDisplay(shown, sizeof(shown));
    pos += snprintf(buf + pos, 1024 - pos, "Name:          %s\n", shown);
  }
  pos += snprintf(buf + pos, 1024 - pos, "Friendly Name: %s\n",
                  gSettings.espnowFriendlyName.length() > 0 ? gSettings.espnowFriendlyName.c_str() : "(not set)");
  pos += snprintf(buf + pos, 1024 - pos, "Room:          %s\n",
                  gSettings.espnowRoom.length() > 0 ? gSettings.espnowRoom.c_str() : "(not set)");
  pos += snprintf(buf + pos, 1024 - pos, "Zone:          %s\n",
                  gSettings.espnowZone.length() > 0 ? gSettings.espnowZone.c_str() : "(not set)");
  pos += snprintf(buf + pos, 1024 - pos, "Tags:          %s\n",
                  gSettings.espnowTags.length() > 0 ? gSettings.espnowTags.c_str() : "(none)");
  pos += snprintf(buf + pos, 1024 - pos, "Stationary:    %s\n",
                  gSettings.espnowStationary ? "true" : "false");

  // Show mesh role
  const char* roleStr = "worker";
  if (gSettings.meshRole == MESH_ROLE_MASTER) roleStr = "master";
  else if (gSettings.meshRole == MESH_ROLE_BACKUP_MASTER) roleStr = "backup";
  pos += snprintf(buf + pos, 1024 - pos, "Mesh Role:     %s\n", roleStr);

  uint8_t myMac[6];
  espnowSelfStaMac(myMac);
  pos += snprintf(buf + pos, 1024 - pos, "MAC:           %s", MAC_STR(myMac));

  return buf;
}

// ==========================
// Master Aggregation CLI Commands (Phase 3)
// ==========================

// ---- What the listings say about room and tag membership ---------------------

// printf onto the end of a reply; a reply that is full stays as it is.
__attribute__((format(printf, 4, 5)))
static void groupTextAppend(char* out, size_t outLen, size_t& pos, const char* format, ...) {
  if (!out || pos + 1 >= outLen) return;
  va_list args;
  va_start(args, format);
  const int n = vsnprintf(out + pos, outLen - pos, format, args);
  va_end(args);
  if (n > 0) pos = (pos + (size_t)n < outLen) ? pos + (size_t)n : outLen - 1;
}

// The mark a listing puts after a peer whose announced room or tags were not
// accepted on this device: " [pending: room, tags a,b]". Empty when all of it
// is accepted. A listing shows what a peer announces; only this mark tells it
// from what room and tag commands go by.
static void groupPendingMark(const uint8_t* mac, const char* room, const char* tags, char* out, size_t outLen) {
  out[0] = '\0';
  EspNowGroupView view;
  espnowGroupView(mac, room, tags, view);
  if (view.pendingRoom[0] && view.pendingTags[0]) {
    snprintf(out, outLen, " [pending: room, tags %s]", view.pendingTags);
  } else if (view.pendingRoom[0]) {
    snprintf(out, outLen, " [pending: room]");
  } else if (view.pendingTags[0]) {
    snprintf(out, outLen, " [pending: tags %s]", view.pendingTags);
  }
}
constexpr size_t kGroupPendingMarkCap = 96;  // the longest mark: every announced tag pending

// What of a listed peer's announced "room" and "tags" is not accepted here, as
// JSON fields next to them: "pendingRoom" and "pendingTags", each only when
// there is something. A listing of the whole mesh has to fit one command
// result, so it carries no second copy of what is accepted (espnowgroups json
// has all of it). The texts are handed over as plain pointers so that
// ArduinoJson copies them: they live in a local view.
static void groupPendingToJson(JsonObject o, const uint8_t* mac, const char* room, const char* tags) {
  EspNowGroupView view;
  espnowGroupView(mac, room, tags, view);
  const char* pendingRoom = view.pendingRoom;
  const char* pendingTags = view.pendingTags;
  if (pendingRoom[0]) o["pendingRoom"] = pendingRoom;
  if (pendingTags[0]) o["pendingTags"] = pendingTags;
}

// One block for the JSON listings and the replies of the membership commands,
// made at the first use and kept. Sixteen peers with their rooms and tags do
// not fit the 1 KB the text listings use; a command result may be this long.
constexpr size_t kGroupReplyCap = CMD_RESULT_MAX;
static char* groupReplyBuffer() {
  static char* sReply = nullptr;
  if (!sReply) sReply = (char*)ps_alloc(kGroupReplyCap, AllocPref::PreferPsram, "espnow.groups");
  if (sReply) sReply[0] = '\0';
  return sReply;
}

// Whether the document, with `tailBytes` kept for the fields that follow the
// list, still fits the reply block.
static bool groupJsonFits(JsonDocument& doc, size_t tailBytes) {
  return measureJson(doc) + tailBytes <= kGroupReplyCap;
}

// A JSON reply has to fit the reply block with its last fields. When the entry
// just added to `list` made it too long, that entry is taken out again and
// counted; the reply then says how many are not shown.
static void groupJsonKeepFit(JsonDocument& doc, JsonArray list, int& notShown, size_t tailBytes) {
  if (groupJsonFits(doc, tailBytes)) return;
  list.remove(list.size() - 1);
  notShown++;
}

// Writes the JSON reply into the reply block. `tooLong` is the refusal for a
// document that does not fit even so (or could not be built).
static const char* groupJsonReply(JsonDocument& doc, char* reply, int notShown, const char* tooLong) {
  if (notShown > 0) doc["notShown"] = notShown;
  if (doc.overflowed() || measureJson(doc) >= kGroupReplyCap) return tooLong;
  serializeJson(doc, reply, kGroupReplyCap);
  return reply;
}
constexpr char kListingJsonTooLong[] =
    "{\"schema\":1,\"ok\":false,\"error\":\"Out of memory for the reply\"}";
constexpr char kListingJsonHint[] =
    "a peer's value: run it remotely with 'espnowremote <peer> <target-user> <target-pass> <cmd>' then read the "
    "reply with 'espnowmessages json'; a peer's name/room/tags: 'espnowrequestmeta <peer>'";
// What a listing keeps free for "count", "notShown" and the hint after its list.
constexpr size_t kListingJsonTailBytes = sizeof(kListingJsonHint) + 64;

// Shared by the espnowdevices json CLI branch and the web metadata handler so
// the per-peer metadata shape lives in exactly one place.
void espnowSerializeMeshPeerMeta(JsonObject o, const MeshPeerMeta& m) {
  MeshPeerHealth* health = getMeshPeerHealth(m.mac, false);
  bool alive = health ? isMeshPeerAlive(health) : false;
  uint32_t lastContact = 0;
  if (health) {
    lastContact = health->lastMeshHeartbeatMs;
    if (health->lastRxActivityMs > lastContact) lastContact = health->lastRxActivityMs;
  }
  uint32_t ageSec = lastContact ? ((millis() - lastContact) / 1000) : 0;
  o["mac"]          = String(MAC_STR(m.mac));
  o["deviceName"]   = m.name;          // matches web's "deviceName"
  o["friendlyName"] = m.friendlyName;
  o["room"]         = m.room;
  o["zone"]         = m.zone;
  o["tags"]         = m.tags;
  // room and tags are what the peer announces; what of it room and tag
  // commands do not go by yet follows as pendingRoom / pendingTags.
  groupPendingToJson(o, m.mac, m.room, m.tags);
  o["stationary"]   = m.stationary;
  o["online"]       = alive;
  o["lastSeenSec"]  = ageSec;
  o["source"]       = "mesh";
}

// Bounded reply appender, defined with the topology results below: the
// cursor never passes the end of the buffer, whatever a row needs.
static bool appendTopologyOutput(char*& cursor, size_t& remaining,
                                 const char* format, ...);
// A list stops taking rows below this much room, so that its closing lines
// are always written.
static constexpr size_t kListTailReserve = 512;

const char* cmd_espnow_devices(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();

  // JSON: all-peers dump of the synced metadata cache (gMeshPeerMeta) in one
  // call — the BLE/CLI parity for the web's per-peer /api/espnow/metadata, but
  // for the whole mesh at once. Same per-peer shape (espnowSerializeMeshPeerMeta)
  // the web handler now uses. This is the on-device source; no per-peer
  // round-trip or creds, available whether or not the web is compiled in.
  if (argWantsJson(argsInput)) {
    char* reply = groupReplyBuffer();
    if (!reply) return kCommandReplyOutOfMemory;
    PSRAM_JSON_DOC(doc);
    doc["schema"] = 1;
    JsonArray devs = doc["devices"].to<JsonArray>();
    // A full table with long names does not fit one command result. The count
    // covers every device; the ones that did not fit are counted in notShown,
    // so the reply always parses.
    int count = 0;
    int notShown = 0;
    for (int i = 0; i < gMeshPeerSlots; i++) {
      if (!gMeshPeerMeta[i].isActive) continue;
      count++;
      espnowSerializeMeshPeerMeta(devs.add<JsonObject>(), gMeshPeerMeta[i]);
      groupJsonKeepFit(doc, devs, notShown, kListingJsonTailBytes);
    }
    doc["count"] = count;
    doc["hint"] = kListingJsonHint;
    return groupJsonReply(doc, reply, notShown, kListingJsonTooLong);
  }

  char* buf = getDebugBuffer();
  char* cursor = buf;
  size_t remaining = GLOBAL_DEBUG_BUFFER_SIZE;
  appendTopologyOutput(cursor, remaining, "=== Mesh Devices ===\n");

  int count = 0;
  bool listFull = false;
  for (int i = 0; i < gMeshPeerSlots; i++) {
    if (!gMeshPeerMeta[i].isActive) continue;
    count++;
    if (listFull) continue;
    if (remaining < kListTailReserve) {
      listFull = true;
      appendTopologyOutput(cursor, remaining, "  ... (truncated)\n");
      continue;
    }

    // Determine online status from MeshPeerHealth
    MeshPeerHealth* health = getMeshPeerHealth(gMeshPeerMeta[i].mac, false);
    bool alive = health ? isMeshPeerAlive(health) : false;
    uint32_t lastContact = 0;
    if (health) {
      lastContact = health->lastMeshHeartbeatMs;
      if (health->lastRxActivityMs > lastContact) lastContact = health->lastRxActivityMs;
    }
    uint32_t ageSec = lastContact ? ((millis() - lastContact) / 1000) : 0;

    const char* displayName = gMeshPeerMeta[i].friendlyName[0]
      ? gMeshPeerMeta[i].friendlyName : gMeshPeerMeta[i].name;
    if (!displayName[0]) displayName = MAC_STR(gMeshPeerMeta[i].mac);

    char zoneBuf[34] = "";
    if (gMeshPeerMeta[i].zone[0]) snprintf(zoneBuf, sizeof(zoneBuf), "/%s", gMeshPeerMeta[i].zone);
    appendTopologyOutput(cursor, remaining, "  %s%s [%s%s] %s",
                         displayName,
                         gMeshPeerMeta[i].room[0] ? "" : "",
                         gMeshPeerMeta[i].room[0] ? gMeshPeerMeta[i].room : "unassigned",
                         zoneBuf,
                         alive ? "(online" : "(offline");
    if (alive && health) {
      appendTopologyOutput(cursor, remaining, ", %lus ago", (unsigned long)ageSec);
    }
    char pendingMark[kGroupPendingMarkCap];
    groupPendingMark(gMeshPeerMeta[i].mac, gMeshPeerMeta[i].room, gMeshPeerMeta[i].tags, pendingMark,
                     sizeof(pendingMark));
    appendTopologyOutput(cursor, remaining, ")%s\n", pendingMark);
  }

  if (count == 0) {
    appendTopologyOutput(cursor, remaining, "  (no peer metadata received yet)\n");
  }
  appendTopologyOutput(cursor, remaining, "Total: %d devices", count);
  emitListingTrailer("discovered/paired mesh peers",
                     "a peer's value: run it remotely with 'espnowremote <peer> <target-user> <target-pass> <cmd>' then read the reply with 'espnowmessages json'; a peer's name/room/tags: 'espnowrequestmeta <peer>'");
  return buf;
}

const char* cmd_espnow_rooms(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();

  if (argWantsJson(argsInput)) {
    char* reply = groupReplyBuffer();
    if (!reply) return kCommandReplyOutOfMemory;
    PSRAM_JSON_DOC(doc);
    doc["schema"] = 1;
    JsonArray roomsArr = doc["rooms"].to<JsonArray>();
    const char* seen[MESH_PEER_MAX];
    int seenCount = 0;
    int notShown = 0;  // devices left out because the reply would not fit
    for (int i = 0; i < gMeshPeerSlots; i++) {
      if (!gMeshPeerMeta[i].isActive) continue;
      const char* room = gMeshPeerMeta[i].room[0] ? gMeshPeerMeta[i].room : "Unassigned";
      bool dup = false;
      for (int r = 0; r < seenCount; r++) if (strcmp(seen[r], room) == 0) { dup = true; break; }
      if (dup || seenCount >= MESH_PEER_MAX) continue;
      seen[seenCount++] = room;
      JsonObject ro = roomsArr.add<JsonObject>();
      ro["room"] = room;
      JsonArray devs = ro["devices"].to<JsonArray>();
      for (int j = 0; j < gMeshPeerSlots; j++) {
        if (!gMeshPeerMeta[j].isActive) continue;
        const char* r2 = gMeshPeerMeta[j].room[0] ? gMeshPeerMeta[j].room : "Unassigned";
        if (strcmp(r2, room) != 0) continue;
        MeshPeerHealth* h = getMeshPeerHealth(gMeshPeerMeta[j].mac, false);
        JsonObject d = devs.add<JsonObject>();
        const char* dn = gMeshPeerMeta[j].friendlyName[0] ? gMeshPeerMeta[j].friendlyName : gMeshPeerMeta[j].name;
        d["name"]   = String(dn[0] ? dn : MAC_STR(gMeshPeerMeta[j].mac));
        d["tags"]   = gMeshPeerMeta[j].tags;
        d["online"] = h ? isMeshPeerAlive(h) : false;
        // The rooms are the announced ones. "accepted" says whether a command
        // to this room reaches the device; "pendingTags", when there are any,
        // which of its tags a tag command does not go by yet.
        EspNowGroupView view;
        espnowGroupView(gMeshPeerMeta[j].mac, gMeshPeerMeta[j].room, gMeshPeerMeta[j].tags, view);
        const char* pendingTags = view.pendingTags;
        d["accepted"] = gMeshPeerMeta[j].room[0] != '\0' && view.pendingRoom[0] == '\0';
        if (pendingTags[0]) d["pendingTags"] = pendingTags;
        groupJsonKeepFit(doc, devs, notShown, kListingJsonTailBytes);
      }
      // A room none of whose devices fit is not shown as an empty room.
      if (devs.size() == 0) roomsArr.remove(roomsArr.size() - 1);
    }
    doc["count"] = seenCount;
    doc["hint"] = kListingJsonHint;
    return groupJsonReply(doc, reply, notShown, kListingJsonTooLong);
  }

  char* buf = getDebugBuffer();
  char* cursor = buf;
  size_t remaining = GLOBAL_DEBUG_BUFFER_SIZE;
  appendTopologyOutput(cursor, remaining, "=== Rooms ===\n");

  // Collect unique room names
  const char* rooms[MESH_PEER_MAX];
  int roomCount = 0;
  for (int i = 0; i < gMeshPeerSlots; i++) {
    if (!gMeshPeerMeta[i].isActive) continue;
    const char* room = gMeshPeerMeta[i].room[0] ? gMeshPeerMeta[i].room : "Unassigned";
    bool found = false;
    for (int r = 0; r < roomCount; r++) {
      if (strcmp(rooms[r], room) == 0) { found = true; break; }
    }
    if (!found && roomCount < MESH_PEER_MAX) rooms[roomCount++] = room;
  }

  bool listFull = false;
  for (int r = 0; r < roomCount && !listFull; r++) {
    appendTopologyOutput(cursor, remaining, "%s:\n", rooms[r]);
    for (int i = 0; i < gMeshPeerSlots; i++) {
      if (!gMeshPeerMeta[i].isActive) continue;
      const char* room = gMeshPeerMeta[i].room[0] ? gMeshPeerMeta[i].room : "Unassigned";
      if (strcmp(room, rooms[r]) != 0) continue;

      MeshPeerHealth* health = getMeshPeerHealth(gMeshPeerMeta[i].mac, false);
      bool alive = health ? isMeshPeerAlive(health) : false;

      const char* displayName = gMeshPeerMeta[i].friendlyName[0]
        ? gMeshPeerMeta[i].friendlyName : gMeshPeerMeta[i].name;
      if (!displayName[0]) displayName = MAC_STR(gMeshPeerMeta[i].mac);

      if (remaining < kListTailReserve) {
        listFull = true;
        appendTopologyOutput(cursor, remaining, "  ...\n");
        break;
      }
      char pendingMark[kGroupPendingMarkCap];
      groupPendingMark(gMeshPeerMeta[i].mac, gMeshPeerMeta[i].room, gMeshPeerMeta[i].tags, pendingMark,
                       sizeof(pendingMark));
      appendTopologyOutput(cursor, remaining, "  %s [%s] (%s)%s\n",
                           displayName,
                           gMeshPeerMeta[i].tags[0] ? gMeshPeerMeta[i].tags : "-",
                           alive ? "online" : "offline", pendingMark);
    }
  }

  if (roomCount == 0) {
    appendTopologyOutput(cursor, remaining, "  (no peer metadata received yet)");
  }
  emitListingTrailer("discovered/paired mesh peers",
                     "a peer's value: run it remotely with 'espnowremote <peer> <target-user> <target-pass> <cmd>' then read the reply with 'espnowmessages json'; a peer's name/room/tags: 'espnowrequestmeta <peer>'");
  return buf;
}

const char* cmd_espnow_find(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  String query = argsInput;
  query.trim();
  if (query.length() == 0) return "Error: invalid arguments — Usage: espnowfind <query> — search by name, room, or tag";

  query.toLowerCase();
  char* buf = getDebugBuffer();
  size_t pos = 0;  // groupTextAppend keeps it inside the buffer
  int matches = 0;

  for (int i = 0; i < gMeshPeerSlots; i++) {
    if (!gMeshPeerMeta[i].isActive) continue;

    // Check name, friendlyName, room, zone, tags (case-insensitive)
    String name = gMeshPeerMeta[i].name; name.toLowerCase();
    String friendly = gMeshPeerMeta[i].friendlyName; friendly.toLowerCase();
    String room = gMeshPeerMeta[i].room; room.toLowerCase();
    String zone = gMeshPeerMeta[i].zone; zone.toLowerCase();
    String tags = gMeshPeerMeta[i].tags; tags.toLowerCase();

    if (name.indexOf(query) >= 0 || friendly.indexOf(query) >= 0 ||
        room.indexOf(query) >= 0 || zone.indexOf(query) >= 0 ||
        tags.indexOf(query) >= 0) {
      matches++;
      const char* displayName = gMeshPeerMeta[i].friendlyName[0]
        ? gMeshPeerMeta[i].friendlyName : gMeshPeerMeta[i].name;
      char pendingMark[kGroupPendingMarkCap];
      groupPendingMark(gMeshPeerMeta[i].mac, gMeshPeerMeta[i].room, gMeshPeerMeta[i].tags, pendingMark,
                       sizeof(pendingMark));
      groupTextAppend(buf, 1024, pos, "  %s [%s/%s] tags=%s%s\n",
                      displayName,
                      gMeshPeerMeta[i].room[0] ? gMeshPeerMeta[i].room : "-",
                      gMeshPeerMeta[i].zone[0] ? gMeshPeerMeta[i].zone : "-",
                      gMeshPeerMeta[i].tags[0] ? gMeshPeerMeta[i].tags : "-", pendingMark);
      if (pos >= 900) break;
    }
  }

  if (matches == 0) {
    snprintf(buf, 1024, "No devices matching '%s'", argsInput.c_str());
  } else {
    emitListingTrailer("discovered/paired mesh peers",
                       "a peer's value: run it remotely with 'espnowremote <peer> <target-user> <target-pass> <cmd>' then read the reply with 'espnowmessages json'; a peer's name/room/tags: 'espnowrequestmeta <peer>'");
  }
  return buf;
}

// ---- Group commands and the membership they go by -----------------------------

// Which group a command goes to.
enum class GroupKind : uint8_t { Room, Tag };

// Sends "user:pass:command" to every paired peer that is a member of the group
// and says in the reply how many were left out. A member is a peer whose room
// or tag was accepted on this device. A peer that only announces it gets
// nothing: the frame carries an account's password, and pairing gives a peer
// an encrypted link, not that password.
static const char* groupCommandRun(GroupKind kind, const String& target, const String& user, const String& pass,
                                   const String& command) {
  if (!gEspNow || !gEspNow->initialized) return "Error: ESP-NOW not initialized. Run 'openespnow' first.";
  // Same rule as 'espnowremote': the frame carries a login and is only ever
  // sent encrypted, which needs a mesh passphrase.
  if (!gEspNow->encryptionEnabled) {
    return "Error: ESP-NOW encryption required. Set a passphrase with "
           "'espnowsetpassphrase <mesh> <passphrase>' and pair securely.";
  }
  const bool isRoom = (kind == GroupKind::Room);
  if (!isRoom) {
    // A tag list would have to mean "all of them" or "any of them", and the
    // frame carries a password either way. One tag, said exactly.
    const char* oneTag;
    size_t oneTagLen;
    if (!espnowgroup::singleTag(target.c_str(), oneTag, oneTagLen)) {
      return "Error: A tag command goes to one tag, and a tag has no comma. Run it once per tag: "
             "espnowtagcmd <tag> <target-user> <target-pass> <command>";
    }
  }
  const String safeCommand = redactCmdForAudit(command);
  const char* const where = isRoom ? "in room" : "with tag";

  char payload[ESPNOW_V4_MAX_PLAINTEXT];
  if (user.length() + pass.length() + command.length() + 2 >= sizeof(payload)) {
    return "Error: command too long for one encrypted ESP-NOW frame (credentials and command must fit 201 bytes)";
  }
  snprintf(payload, sizeof(payload), "%s:%s:%s", user.c_str(), pass.c_str(), command.c_str());

  if (!ensureDebugBuffer()) return kCommandReplyOutOfMemory;
  char* buf = getDebugBuffer();
  const size_t cap = 1024;
  size_t pos = 0;
  buf[0] = '\0';
  int matched = 0;  // members of the group
  int sent = 0;     // members whose frame went out or was parked for their session
  int queuedCount = 0;  // of those, parked: they go out when that member's session opens
  int listed = 0;
  int skipped = 0;
  char skippedNames[120] = "";
  size_t skippedPos = 0;
  bool skippedCut = false;
  char refused[160] = "";  // names of the members that did not take the command
  size_t refusedPos = 0;
  bool refusedCut = false;
  char reason[64] = "";  // why the first of them did not

  for (int i = 0; i < gEspNow->deviceCount; i++) {
    // Records are added and removed on this task only, so `dev` stays this
    // peer's; what it holds is copied under the lock, because espnow_task
    // stores announcements into it.
    const EspNowDevice& dev = gEspNow->devices[i];
    if (isSelfMac(dev.mac)) continue;
    espnowgroup::Membership m;
    if (!groupSnapshotOf(dev.mac, m)) continue;
    char who[32];
    groupPeerLabel(dev, who, sizeof(who));
    const bool member = isRoom ? espnowgroup::inRoom(m, target.c_str()) : espnowgroup::hasTag(m, target.c_str());
    if (!member) {
      const bool claims = isRoom ? espnowgroup::claimsRoom(m, target.c_str())
                                 : espnowgroup::claimsTag(m, target.c_str());
      if (claims) {
        skipped++;
        // Named while they fit; the count covers the rest.
        if (skippedPos + strlen(who) + 2 < sizeof(skippedNames) - 6) {
          groupTextAppend(skippedNames, sizeof(skippedNames), skippedPos, "%s%s", skippedPos ? ", " : "", who);
        } else {
          skippedCut = true;
        }
      }
      continue;
    }
    matched++;

    // Encrypt-or-wait. The payload carries credentials, so it never goes out
    // in plaintext. A peer without a session is not skipped: the frame is
    // parked, the handshake is started and the frame goes out when the session
    // is up (or its timeout drops it). So `sent` counts frames accepted for
    // delivery, not frames on the air.
    char status[64] = "";
    if (!v4_send_encrypted_or_queue(dev.mac, ESPNOW_V4_TYPE_CMD, ESPNOW_V4_FLAG_ACK_REQ, generateMessageId(),
                                    (const uint8_t*)payload, (uint16_t)strlen(payload), 1, status,
                                    sizeof(status))) {
      if (!reason[0]) strlcpy(reason, status[0] ? status : "send failed", sizeof(reason));
      // A name goes in whole or not at all; ", ..." stands for the rest.
      if (refusedPos + strlen(who) + 8 <= sizeof(refused)) {
        groupTextAppend(refused, sizeof(refused), refusedPos, "%s%s", refusedPos ? ", " : "", who);
      } else if (!refusedCut) {
        refusedCut = true;
        groupTextAppend(refused, sizeof(refused), refusedPos, ", ...");
      }
      continue;
    }
    sent++;
    // Every queued status starts with "queued" (v4_send_encrypted_or_queue).
    const bool queued = strncmp(status, "queued", 6) == 0;
    if (queued) queuedCount++;
    // Every member is sent to; the reply names as many as fit beside its last lines.
    if (pos < 360) {
      char macText[18];
      macToDisplay(dev.mac, macText, sizeof(macText));
      groupTextAppend(buf, cap, pos, "  -> %s (%s)%s\n", who, macText,
                      queued ? " queued until its session opens" : "");
      listed++;
    }
  }

  if (matched == 0) {
    // Nothing went out: the reply is the failure alone.
    pos = 0;
    if (isRoom) {
      groupTextAppend(buf, cap, pos,
                      "Error: No devices found in room '%s'. List rooms and members with '%s'.", target.c_str(),
                      espnowgroup::kListCommand);
    } else {
      groupTextAppend(buf, cap, pos,
                      "Error: No devices found with tag '%s'. List devices and their tags with '%s'.",
                      target.c_str(), espnowgroup::kListCommand);
    }
  } else if (sent == 0) {
    pos = 0;
    groupTextAppend(buf, cap, pos,
                    "Error: Command not sent to any of %d device(s) %s '%s' (%s). Check 'espnowstatus' and retry.",
                    matched, where, target.c_str(), reason);
  } else if (sent < matched) {
    // Leads with the failure; the members it went to stay listed below.
    char sentList[400];
    strlcpy(sentList, buf, sizeof(sentList));
    pos = 0;
    char queuedNote[64] = "";
    if (queuedCount > 0) {
      snprintf(queuedNote, sizeof(queuedNote), " (%d of them queued until their session opens)", queuedCount);
    }
    groupTextAppend(buf, cap, pos,
                    "Error: Command sent to %d of %d device(s) %s '%s'%s; not sent to %s (%s). "
                    "Send it to those with 'espnowremote <device> <user> <pass> <command>'.\n%s",
                    sent, matched, where, target.c_str(), queuedNote, refused, reason, sentList);
    if (sent > listed) groupTextAppend(buf, cap, pos, "  ... and %d more\n", sent - listed);
  } else {
    if (sent > listed) groupTextAppend(buf, cap, pos, "  ... and %d more\n", sent - listed);
    cliHint("each device's reply returns asynchronously - read them with 'espnowmessages json'");
    if (queuedCount == sent) {
      // None went out yet: each waits for its member's session to open.
      if (isRoom) {
        groupTextAppend(buf, cap, pos, "Queued '%s' for %d device(s) in %s until their sessions open",
                        safeCommand.c_str(), sent, target.c_str());
      } else {
        groupTextAppend(buf, cap, pos, "Queued '%s' for %d device(s) with tag '%s' until their sessions open",
                        safeCommand.c_str(), sent, target.c_str());
      }
    } else if (isRoom) {
      groupTextAppend(buf, cap, pos, "Sent '%s' to %d device(s) in %s", safeCommand.c_str(), sent, target.c_str());
    } else {
      groupTextAppend(buf, cap, pos, "Sent '%s' to %d device(s) with tag '%s'", safeCommand.c_str(), sent,
                      target.c_str());
    }
    if (queuedCount > 0 && queuedCount < sent) {
      groupTextAppend(buf, cap, pos, " (%d of them queued until their session opens)", queuedCount);
    }
  }
  if (skipped > 0) {
    if (skippedCut) groupTextAppend(skippedNames, sizeof(skippedNames), skippedPos, ", ...");
    groupTextAppend(buf, cap, pos,
                    "\nSkipped %d device(s) whose %s is pending (announced, not accepted here): %s. "
                    "Accept with '%s <name_or_mac|all>'",
                    skipped, isRoom ? "room" : "tag", skippedNames, espnowgroup::kAcceptCommand);
  }
  return buf;
}

const char* cmd_espnow_roomcmd(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  CommandArgs a(argsInput);
  if (!a.hasMinArgs(4)) return "Error: invalid arguments — Usage: espnowroomcmd <room> <user> <pass> <command>";
  return groupCommandRun(GroupKind::Room, a.arg(0), a.arg(1), a.arg(2), a.remaining(2));
}

const char* cmd_espnow_tagcmd(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  CommandArgs a(argsInput);
  if (!a.hasMinArgs(4)) return "Error: invalid arguments — Usage: espnowtagcmd <tag> <user> <pass> <command>";
  return groupCommandRun(GroupKind::Tag, a.arg(0), a.arg(1), a.arg(2), a.remaining(2));
}

// "json" first, then the peer the command names (empty when none is given).
static bool groupCommandArgs(const String& argsInput, String& target) {
  const bool json = argLeadingTokenIsJson(argsInput);
  CommandArgs a(argsInput);
  target = a.arg(json ? 1 : 0);
  return json;
}

// The records a membership command works on: the one peer `target` names, or
// every paired peer for "all" (and for an empty target where the command
// allows it). Returns the refusal to reply with when the target names no
// peer, nullptr otherwise.
static const char* groupCommandTarget(const String& target, bool& all, EspNowDevice*& one) {
  all = (target.length() == 0) || target.equalsIgnoreCase("all");
  one = nullptr;
  if (all) return nullptr;
  uint8_t mac[6];
  if (!resolveDeviceNameOrMac(target, mac)) {
    return "Error: No paired device with that name or address. List them with 'espnowgroups'.";
  }
  // A name two records share would silently mean the first of them, and
  // accepting gives a peer the passwords sent to its room. The lists call
  // such a peer by its address, and so must the admin.
  int sameName = 0;
  for (int i = 0; i < gEspNow->deviceCount; i++) {
    if (gEspNow->devices[i].name.equalsIgnoreCase(target)) sameName++;
  }
  uint8_t asAddress[6];
  const bool byAddress = parseMacAddress(target, asAddress) && memcmp(asAddress, mac, 6) == 0;
  if (sameName > 1 && !byAddress) {
    return "Error: More than one paired device has that name. Use the address; 'espnowgroups' lists them.";
  }
  one = groupDeviceFor(mac);
  if (!one) return "Error: That is this device. Its own room and tags need no acceptance.";
  return nullptr;
}

// What a membership command keeps free for its last fields after the peers.
constexpr size_t kGroupJsonTailBytes = 200;
constexpr char kGroupJsonTooLong[] =
    "{\"schema\":1,\"ok\":false,\"error\":\"Out of memory for the reply. Name one peer instead of all of them\"}";

// One peer of a membership command's JSON reply: what it announces, what is
// accepted and what waits, all from the one copy `m` the command worked on.
// The texts are handed over as plain pointers so that ArduinoJson copies them.
static void groupPeerToJson(JsonObject o, const char* name, const char* mac, const espnowgroup::Membership& m) {
  char pending[espnowgroup::kTagsCap];
  espnowgroup::pendingTags(m, pending, sizeof(pending));
  const char* room = m.room;
  const char* tags = m.tags;
  const char* acceptedRoom = m.acceptedRoom;
  const char* acceptedTags = m.acceptedTags;
  const char* pendingRoom = espnowgroup::roomPending(m) ? m.room : "";
  const char* pendingTags = pending;
  o["mac"] = mac;
  o["name"] = name;
  o["room"] = room;
  o["tags"] = tags;
  o["acceptedRoom"] = acceptedRoom;
  o["acceptedTags"] = acceptedTags;
  o["pendingRoom"] = pendingRoom;
  o["pendingTags"] = pendingTags;
}

// List what every paired peer announces, what was accepted here and what waits.
const char* cmd_espnow_groups(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  if (!gEspNow) return "Error: ESP-NOW not initialized. Run 'openespnow' first.";
  String target;
  const bool json = groupCommandArgs(argsInput, target);
  bool all = true;
  EspNowDevice* one = nullptr;
  if (const char* refusal = groupCommandTarget(target, all, one)) return refusal;
  char* reply = groupReplyBuffer();
  if (!reply) return kCommandReplyOutOfMemory;

  PSRAM_JSON_DOC(doc);
  JsonArray peers;
  if (json) {
    doc["schema"] = 1;
    peers = doc["peers"].to<JsonArray>();
  }
  size_t pos = 0;
  if (!json) groupTextAppend(reply, kGroupReplyCap, pos, "=== Rooms and tags of paired peers ===\n");
  int count = 0;
  int pendingCount = 0;
  int notShown = 0;
  for (int i = 0; i < gEspNow->deviceCount; i++) {
    EspNowDevice& dev = gEspNow->devices[i];
    if (isSelfMac(dev.mac) || (!all && &dev != one)) continue;
    espnowgroup::Membership m;
    if (!groupSnapshotOf(dev.mac, m)) continue;
    char pendingTags[espnowgroup::kTagsCap];
    espnowgroup::pendingTags(m, pendingTags, sizeof(pendingTags));
    const bool roomPending = espnowgroup::roomPending(m);
    count++;
    if (roomPending || pendingTags[0]) pendingCount++;
    char who[32];
    groupPeerLabel(dev, who, sizeof(who));
    char macText[18];
    macToDisplay(dev.mac, macText, sizeof(macText));
    if (json) {
      groupPeerToJson(peers.add<JsonObject>(), who, macText, m);
      groupJsonKeepFit(doc, peers, notShown, kGroupJsonTailBytes);
      continue;
    }
    // A peer takes up to about 450 bytes; the rest of the block is for the last lines.
    if (pos + 450 + 260 > kGroupReplyCap) {
      notShown++;
      continue;
    }
    char text[espnowgroup::kDescribeCap];
    groupTextAppend(reply, kGroupReplyCap, pos, "%s (%s)\n", who, macText);
    espnowgroup::describe(text, sizeof(text), m.room, m.tags);
    groupTextAppend(reply, kGroupReplyCap, pos, "  announced: %s\n", text);
    espnowgroup::describe(text, sizeof(text), m.acceptedRoom, m.acceptedTags);
    groupTextAppend(reply, kGroupReplyCap, pos, "  accepted:  %s\n", text);
    espnowgroup::describe(text, sizeof(text), roomPending ? m.room : "", pendingTags);
    groupTextAppend(reply, kGroupReplyCap, pos, "  pending:   %s\n", text);
  }
  if (json) {
    doc["count"] = count;
    doc["pendingCount"] = pendingCount;
    return groupJsonReply(doc, reply, notShown, kGroupJsonTooLong);
  }
  if (count == 0) {
    groupTextAppend(reply, kGroupReplyCap, pos, "  (no paired peers)\n");
  }
  if (notShown > 0) {
    groupTextAppend(reply, kGroupReplyCap, pos, "... %d more peer(s) not shown; name one: %s <name_or_mac>\n", notShown,
                    espnowgroup::kListCommand);
  }
  groupTextAppend(reply, kGroupReplyCap, pos,
                  "%d peer(s), %d with pending room or tags. Room and tag commands go only by what is accepted.\n"
                  "Accept what a peer announces: %s <name_or_mac|all>. Take it back: %s <name_or_mac|all>.",
                  count, pendingCount, espnowgroup::kAcceptCommand, espnowgroup::kDropCommand);
  return reply;
}

// Accept (accepting) what the named peers announce right now, or take back
// (!accepting) what was accepted for them. The reply states the accepted room
// and tags of each peer afterwards: an announcement may have changed since
// the list was read.
static const char* groupAcceptOrDrop(const String& argsInput, bool accepting) {
  if (!gEspNow) return "Error: ESP-NOW not initialized. Run 'openespnow' first.";
  String target;
  const bool json = groupCommandArgs(argsInput, target);
  if (target.length() == 0) {
    return accepting ? "Error: invalid arguments — Usage: espnowgroupaccept [json] <name_or_mac|all>"
                  : "Error: invalid arguments — Usage: espnowgroupdrop [json] <name_or_mac|all>";
  }
  bool all = false;
  EspNowDevice* one = nullptr;
  if (const char* refusal = groupCommandTarget(target, all, one)) return refusal;
  char* reply = groupReplyBuffer();
  if (!reply) return kCommandReplyOutOfMemory;

  PSRAM_JSON_DOC(doc);
  JsonArray peers;
  if (json) {
    doc["schema"] = 1;
    peers = doc["peers"].to<JsonArray>();
  }
  size_t pos = 0;
  int count = 0;
  int changedCount = 0;
  int notShown = 0;
  for (int i = 0; i < gEspNow->deviceCount; i++) {
    EspNowDevice& dev = gEspNow->devices[i];
    if (isSelfMac(dev.mac) || (!all && &dev != one)) continue;
    count++;
    espnowgroup::Membership before;
    espnowgroup::Membership m;
    bool changed = false;
    {
      // Read, decide and write in one step: the peer's announcements are
      // stored on another task, and one that lands now comes either before
      // (and is what gets accepted) or after (and is judged against this).
      GroupLockGuard lock;
      before = groupMembershipOf(dev);
      m = before;
      changed = accepting ? espnowgroup::acceptAnnounced(m) : espnowgroup::dropAccepted(m);
      if (changed) {
        dev.acceptedRoom = m.acceptedRoom;
        dev.acceptedTags = m.acceptedTags;
      }
    }
    if (changed) changedCount++;
    char who[32];
    groupPeerLabel(dev, who, sizeof(who));
    char macText[18];
    macToDisplay(dev.mac, macText, sizeof(macText));
    char text[espnowgroup::kDescribeCap];
    if (accepting) {
      espnowgroup::describe(text, sizeof(text), m.acceptedRoom, m.acceptedTags);
      if (changed) logSystemEvent("ESPNOW", "%s: accepted for group commands: %s", who, text);
    } else {
      espnowgroup::describe(text, sizeof(text), before.acceptedRoom, before.acceptedTags);
      if (changed) logSystemEvent("ESPNOW", "%s: no longer accepted for group commands: %s", who, text);
    }
    if (json) {
      JsonObject o = peers.add<JsonObject>();
      groupPeerToJson(o, who, macText, m);
      o["changed"] = changed;
      groupJsonKeepFit(doc, peers, notShown, kGroupJsonTailBytes);
      continue;
    }
    // Every named peer is handled; the reply lists as many as fit and counts all.
    if (pos + 260 + 320 > kGroupReplyCap) {
      notShown++;
      continue;
    }
    if (accepting) {
      const bool announcesNothing = (m.room[0] == '\0' && m.tags[0] == '\0');
      groupTextAppend(reply, kGroupReplyCap, pos, "%s (%s): %s %s%s\n", who, macText,
                      announcesNothing ? "announces no room or tags; accepted" : "accepted", text,
                      (changed || announcesNothing) ? "" : " (as before)");
    } else {
      groupTextAppend(reply, kGroupReplyCap, pos, "%s (%s): %s %s\n", who, macText,
                      changed ? "no longer accepted:" : "nothing was accepted;", changed ? text : "no change");
    }
  }

  // Saved once for all peers, and only when something changed.
  const bool saved = (changedCount == 0) || saveEspNowDevices();
  if (json) {
    doc["ok"] = saved;
    doc["count"] = count;
    doc["changed"] = changedCount;
    doc["saved"] = saved;
    if (!saved) doc["error"] = "The device registry could not be saved; the change is lost at a restart";
    return groupJsonReply(doc, reply, notShown, kGroupJsonTooLong);
  }
  if (count == 0) {
    groupTextAppend(reply, kGroupReplyCap, pos, "No paired peers.\n");
  }
  if (notShown > 0) {
    groupTextAppend(reply, kGroupReplyCap, pos, "... %d more peer(s) not shown; see them with '%s'\n", notShown,
                    espnowgroup::kListCommand);
  }
  if (accepting) {
    groupTextAppend(reply, kGroupReplyCap, pos,
                    "%d peer(s), %d changed. Room and tag commands go to a peer by what is accepted for it.", count,
                    changedCount);
  } else {
    groupTextAppend(reply, kGroupReplyCap, pos,
                    "%d peer(s), %d changed. What such a peer announces waits until accepted again: %s <name_or_mac|all>.",
                    count, changedCount, espnowgroup::kAcceptCommand);
  }
  if (!saved) {
    groupTextAppend(reply, kGroupReplyCap, pos,
                    "\nThe device registry could not be saved: the change holds until a restart. "
                    "Check the filesystem and run the command again.");
  }
  return reply;
}

const char* cmd_espnow_groupaccept(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  return groupAcceptOrDrop(argsInput, true);
}

const char* cmd_espnow_groupdrop(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  return groupAcceptOrDrop(argsInput, false);
}

// ESP-NOW heartbeat mode command
const char* cmd_espnow_hbmode(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  CommandArgs a(argsInput);

  if (a.count() == 0) {
    const char* mode = gSettings.meshHeartbeatBroadcast ? "public" : "private";
    const char* desc = gSettings.meshHeartbeatBroadcast
      ? "Heartbeats broadcast to all devices (discovery enabled)"
      : "Heartbeats sent only to paired devices (discovery disabled)";
    snprintf(getDebugBuffer(), 1024, "Heartbeat mode: %s\n%s", mode, desc);
    return getDebugBuffer();
  }

  String hbArg = a.arg(0);
  hbArg.toLowerCase();
  if (hbArg == "public" || hbArg == "broadcast") {
    setSetting(gSettings.meshHeartbeatBroadcast, true);
    return "Heartbeat mode set to public (broadcast). Unpaired devices can now be discovered.";
  } else if (hbArg == "private" || hbArg == "unicast") {
    setSetting(gSettings.meshHeartbeatBroadcast, false);
    return "Heartbeat mode set to private (unicast). Only paired devices will receive heartbeats.";
  }
  
  return "Error: invalid arguments — Usage: espnowhbmode [public|private]";
}

// Mesh role command
const char* cmd_espnow_meshrole(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  CommandArgs a(argsInput);

  if (argWantsJson(argsInput)) {
    PSRAM_JSON_DOC(doc);
    doc["schema"]        = 1;
    doc["role"]          = getMeshRoleString(gSettings.meshRole);
    doc["masterMac"]     = gSettings.meshMasterMac;
    doc["backupEnabled"] = gSettings.meshBackupEnabled;
    doc["backupMac"]     = gSettings.meshBackupMac;
    serializeJson(doc, getDebugBuffer(), 1024);
    return getDebugBuffer();
  }

  if (a.count() == 0) {
    int pos = 0;
    char* buf = getDebugBuffer();
    pos += snprintf(buf + pos, 1024 - pos, "Mesh role: %s", getMeshRoleString(gSettings.meshRole));
    if (gSettings.meshMasterMac.length() > 0) {
      pos += snprintf(buf + pos, 1024 - pos, "\nMaster MAC: %s", gSettings.meshMasterMac.c_str());
    }
    pos += snprintf(buf + pos, 1024 - pos, "\nBackup enabled: %s", gSettings.meshBackupEnabled ? "yes" : "no");
    if (gSettings.meshBackupEnabled && gSettings.meshBackupMac.length() > 0) {
      pos += snprintf(buf + pos, 1024 - pos, "\nBackup MAC: %s", gSettings.meshBackupMac.c_str());
    }
    return buf;
  }
  
  String role = a.arg(0);
  role.toLowerCase();
  if (role != "worker" && role != "master" && role != "backup") {
    return "Error: invalid arguments — Usage: espnowmeshrole [worker|master|backup]";
  }
  // A role set here ends a failover promotion: the change is made from the
  // configured role (backup master), so it is saved even when the running
  // role already matches.
  if (gBackupPromoted) {
    gBackupPromoted = false;
    gSettings.meshRole = (uint8_t)MESH_ROLE_BACKUP_MASTER;
  }
  if (role == "worker") {
    setSetting(gSettings.meshRole, (uint8_t)MESH_ROLE_WORKER);
    BROADCAST_PRINTF("[MESH] Role set to worker");
    return "Role set to worker";
  } else if (role == "master") {
    setSetting(gSettings.meshRole, (uint8_t)MESH_ROLE_MASTER);
    setSetting(gSettings.meshMasterMac, String(""));
    BROADCAST_PRINTF("[MESH] Role set to master");
    return "Role set to master";
  } else if (role == "backup") {
    setSetting(gSettings.meshRole, (uint8_t)MESH_ROLE_BACKUP_MASTER);
    BROADCAST_PRINTF("[MESH] Role set to backup master");
    return "Role set to backup master";
  }

  return "Error: invalid arguments — Usage: espnowmeshrole [worker|master|backup]";
}


// V2 fragmentation is now mandatory - command removed

// True when `mac` is this device's own STA or AP address. An address the
// radio cannot report matches nothing.
static bool macIsOwnAddress(const uint8_t mac[6]) {
  uint8_t own[6];
  if (espnowSelfStaMac(own) == ESP_OK && memcmp(mac, own, 6) == 0) return true;
  return espnowSelfApMac(own) == ESP_OK && memcmp(mac, own, 6) == 0;
}

// Mesh master command
const char* cmd_espnow_meshmaster(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  CommandArgs a(argsInput);

  if (a.count() == 0) {
    if (gSettings.meshMasterMac.length() > 0) {
      BROADCAST_PRINTF("Master MAC: %s", gSettings.meshMasterMac.c_str());
    } else {
      BROADCAST_PRINTF("No master assigned");
    }
    return "OK";
  }

  uint8_t mac[6];
  if (!a.argMac(0, mac)) {
    return "Error: Invalid MAC address format. Use: XX:XX:XX:XX:XX:XX";
  }
  if (macIsOwnAddress(mac)) {
    return "Error: Cannot set your own MAC as master MAC";
  }

  // Stored in the one written form, whichever separators were typed.
  setSetting(gSettings.meshMasterMac, macToDisplayStr(mac));
  BROADCAST_PRINTF("[MESH] Master MAC set to %s", gSettings.meshMasterMac.c_str());
  return "OK";
}

// Mesh backup command
const char* cmd_espnow_meshbackup(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  CommandArgs a(argsInput);

  if (a.count() == 0) {
    if (gSettings.meshBackupMac.length() > 0) {
      BROADCAST_PRINTF("Backup MAC: %s", gSettings.meshBackupMac.c_str());
    } else {
      BROADCAST_PRINTF("No backup assigned");
    }
    return "OK";
  }

  uint8_t mac[6];
  if (!a.argMac(0, mac)) {
    return "Error: Invalid MAC address format. Use: XX:XX:XX:XX:XX:XX";
  }
  if (macIsOwnAddress(mac)) {
    return "Error: Cannot set your own MAC as backup MAC";
  }

  // Stored in the one written form, whichever separators were typed.
  setSetting(gSettings.meshBackupMac, macToDisplayStr(mac));
  BROADCAST_PRINTF("[MESH] Backup MAC set to %s", gSettings.meshBackupMac.c_str());
  return "OK";
}

// Backup master enable/disable command
const char* cmd_espnow_backupenable(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  String args = argsInput;
  args.trim();
  args.toLowerCase();

  if (args.length() == 0) {
    if (!ensureDebugBuffer()) return "Error: Debug buffer unavailable";
    snprintf(getDebugBuffer(), 1024, "Backup master: %s", gSettings.meshBackupEnabled ? "enabled" : "disabled");
    return getDebugBuffer();
  }

  bool enable = argIsOn(args);
  bool disable = argIsOff(args);
  if (!enable && !disable) {
    return "Error: invalid arguments — Usage: espnowbackupenable [on|off]";
  }

  setSetting(gSettings.meshBackupEnabled, enable);
  return enable ? "Backup master enabled" : "Backup master disabled";
}

// Mesh topology discovery command
const char* cmd_espnow_meshtopo(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  
  if (!meshEnabled()) {
    return "Error: Mesh mode not enabled. Use 'espnowmode mesh' first.";
  }
  if (!gEspNow || !gEspNow->initialized) {
    return "Error: ESP-NOW not initialized. Run 'openespnow' first.";
  }
  
  int peerCount = 0;
  for (int i = 0; i < gMeshPeerSlots; i++) {
    if (gMeshPeers[i].isActive && !isSelfMac(gMeshPeers[i].mac)) {
      peerCount++;
    }
  }
  
  if (peerCount == 0) {
    esp_now_peer_num_t peerNum;
    esp_now_get_peer_num(&peerNum);
    int pairedCount = peerNum.total_num;
    
    if (pairedCount == 0) {
      return "Error: No mesh peers available. Pair devices using 'espnowpair' or "
             "'espnowpairsecure' first.";
    }
    if (!ensureDebugBuffer()) return kCommandReplyOutOfMemory;
    snprintf(getDebugBuffer(), GLOBAL_DEBUG_BUFFER_SIZE,
             "Error: No mesh peers discovered yet. %d paired device(s) have sent no heartbeat. "
             "Check that they are powered on and in mesh mode.",
             pairedCount);
    return getDebugBuffer();
  }
  
  BROADCAST_PRINTF("[TOPO] Initiating topology discovery for %d peer(s)...", peerCount);
  const int admitted = requestTopologyDiscovery();
  if (admitted < 0) {
    return "Error: Topology state is busy. Run 'espnowmeshtopo' again shortly.";
  }
  if (admitted == 0) {
    if (!ensureDebugBuffer()) return kCommandReplyOutOfMemory;
    snprintf(getDebugBuffer(), GLOBAL_DEBUG_BUFFER_SIZE,
             "Error: Topology request was not sent to any of %d peer(s). "
             "Check 'espnowmeshstatus' and retry.",
             peerCount);
    return getDebugBuffer();
  }
  return "Topology discovery initiated. Use 'espnowtoporesults' to view responses.";
}

// (espnowtimesync and espnowtimestatus: System_ESPNow_MeshTime.cpp.)

static bool appendTopologyOutput(char*& cursor, size_t& remaining,
                                 const char* format, ...) {
  if (!cursor || remaining == 0) return false;
  va_list args;
  va_start(args, format);
  int written = vsnprintf(cursor, remaining, format, args);
  va_end(args);
  if (written < 0) return false;
  if ((size_t)written >= remaining) {
    cursor += remaining - 1;
    remaining = 1;
    return false;
  }
  cursor += written;
  remaining -= (size_t)written;
  return true;
}

// Topology results command. Formatting happens directly from bounded PSRAM
// records into one PSRAM output buffer; there is no intermediate String.
const char* cmd_espnow_toporesults(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();

  TopoStreamsGuard guard("cmd_espnow_toporesults");
  if (gTopoStreamsMutex && !guard.held) {
    return "Error: Topology results are busy. Try again shortly.";
  }

  const uint32_t now = (uint32_t)millis();
  if (gTopoRequestId != 0 && (int32_t)(gTopoRequestTimeout - now) <= 0) {
    const uint32_t expiredRequestId = gTopoRequestId;
    for (int i = 0; i < MAX_CONCURRENT_TOPO_STREAMS; i++) {
      if (gTopoStreams[i].active && gTopoStreams[i].reqId == expiredRequestId) {
        finalizeTopologyStreamLocked(&gTopoStreams[i]);
      }
    }
    gTopoCompletedRequestId = expiredRequestId;
    gTopoRequestId = 0;
    gTopoRequestTimeout = 0;
  }
  if (gTopoRequestId != 0) {
    // A progress reply, not a failure: the web page polls this command while a
    // discovery runs and stops polling at the first failed reply.
    return "Still collecting topology responses; run espnowtoporesults again shortly.";
  }
  if (gTopoCompletedRequestId == 0) {
    return "Error: No topology discovery results are available.";
  }

  int totalStreams = 0;
  for (int i = 0; i < MAX_CONCURRENT_TOPO_STREAMS; i++) {
    if (gTopoStreams[i].occupied &&
        gTopoStreams[i].reqId == gTopoCompletedRequestId) {
      totalStreams++;
    }
  }
  const int totalPages = totalStreams > 0
      ? (totalStreams + TOPO_STREAMS_PER_PAGE - 1) / TOPO_STREAMS_PER_PAGE
      : 1;

  CommandArgs pageArgs(argsInput);
  if (pageArgs.count() > 2) {
    return "Error: Usage: espnowtoporesults [page] [request-id]";
  }
  int requestedPage = 1;
  if (pageArgs.count() >= 1) {
    const String pageText = pageArgs.arg(0);
    if (pageText.length() == 0 || pageText.length() > 2) {
      return "Error: topology page must be a positive number";
    }
    for (size_t i = 0; i < pageText.length(); i++) {
      if (pageText[i] < '0' || pageText[i] > '9') {
        return "Error: topology page must be a positive number";
      }
    }
    if (!parseIntArg(pageText, requestedPage)) return "Error: topology page must be a positive number";
  }

  if (pageArgs.count() == 2) {
    const String requestText = pageArgs.arg(1);
    if (requestText.length() == 0 || requestText.length() > 10) {
      return "Error: topology request ID must be a positive decimal number";
    }
    uint32_t requestedRequestId = 0;
    for (size_t i = 0; i < requestText.length(); i++) {
      const char c = requestText[i];
      if (c < '0' || c > '9') {
        return "Error: topology request ID must be a positive decimal number";
      }
      const uint32_t digit = (uint32_t)(c - '0');
      if (requestedRequestId > (UINT32_MAX - digit) / 10u) {
        return "Error: topology request ID is out of range";
      }
      requestedRequestId = requestedRequestId * 10u + digit;
    }
    if (requestedRequestId == 0) {
      return "Error: topology request ID must be a positive decimal number";
    }
    if (requestedRequestId != gTopoCompletedRequestId) {
      return "Error: topology results changed while paging; restart from page 1";
    }
  }

  if (requestedPage < 1 || requestedPage > totalPages) {
    if (!ensureDebugBuffer()) return "Error: Invalid topology page";
    snprintf(getDebugBuffer(), 1024,
             "Error: topology page must be between 1 and %d", totalPages);
    return getDebugBuffer();
  }

  // Allocate only once valid, renderable results exist. closeespnow releases
  // the buffer; opening the topology page before discovery allocates nothing.
  if (!gTopoOutputBuffer) {
    gTopoOutputBuffer = (char*)ps_alloc(TOPO_OUTPUT_CAPACITY,
                                        AllocPref::RequirePsram, "topo.output");
    if (!gTopoOutputBuffer) {
      return "Error: PSRAM allocation failed for topology output.";
    }
  }

  char* p = gTopoOutputBuffer;
  size_t remaining = TOPO_OUTPUT_CAPACITY;
  bool completeOutput = appendTopologyOutput(
      p, remaining,
      "\n=== Mesh Topology Discovery Results ===\n"
      "Responses received: %d/%d\nRequest ID: %lu\nPage: %d/%d\n\n",
      gTopoResponsesReceived, gExpectedWorkerCount,
      (unsigned long)gTopoCompletedRequestId, requestedPage, totalPages);

  int renderedStreams = 0;
  int matchingStream = 0;
  const int firstStream = (requestedPage - 1) * TOPO_STREAMS_PER_PAGE;
  for (int i = 0; completeOutput && i < MAX_CONCURRENT_TOPO_STREAMS; i++) {
    const TopologyStream& stream = gTopoStreams[i];
    if (!stream.occupied || stream.reqId != gTopoCompletedRequestId) continue;
    if (matchingStream++ < firstStream) continue;
    if (renderedStreams >= TOPO_STREAMS_PER_PAGE) break;
    char senderMac[18];
    macToDisplay(stream.senderMac, senderMac, sizeof(senderMac));
    completeOutput = appendTopologyOutput(
        p, remaining, "%s (%s):%s\n", stream.senderName[0] ? stream.senderName : "Unknown",
        senderMac, stream.receivedPeers < stream.totalPeers ? " [partial]" : "");
    completeOutput = completeOutput && appendTopologyOutput(
        p, remaining, "  Peers: %u\n", (unsigned)stream.totalPeers);
    for (uint16_t peerIndex = 0;
         completeOutput && peerIndex < stream.totalPeers && peerIndex < MESH_PEER_MAX;
         peerIndex++) {
      const TopologyPeerRecord& peer = stream.peers[peerIndex];
      if (!peer.present) {
        completeOutput = appendTopologyOutput(
            p, remaining, "  (missing peer index %u)\n", peerIndex);
        continue;
      }
      char peerMac[18];
      macToDisplay(peer.mac, peerMac, sizeof(peerMac));
      completeOutput = appendTopologyOutput(
          p, remaining, "  \xe2\x86\x92 %s (%s)\n    RSSI: %d dBm\n",
          peer.name[0] ? peer.name : "Unknown", peerMac, (int)peer.rssi);
    }
    if (stream.totalPeers == 0) {
      completeOutput = appendTopologyOutput(p, remaining, "  (no peers)\n");
    }
    completeOutput = completeOutput && appendTopologyOutput(p, remaining, "\n");
    renderedStreams++;
  }

  if (renderedStreams == 0 && completeOutput) {
    completeOutput = appendTopologyOutput(p, remaining, "(no peers responded)\n\n");
  }
  if (completeOutput) {
    if (requestedPage < totalPages) {
      completeOutput = appendTopologyOutput(
          p, remaining, "More results: espnowtoporesults %d %lu\n\n",
          requestedPage + 1, (unsigned long)gTopoCompletedRequestId);
    }
  }
  if (completeOutput) {
    appendTopologyOutput(
        p, remaining,
        "=======================================\n\n"
        "Chain Interpretation:\n"
        "  Devices with mutual peer connections form a chain.\n"
        "  Example: If A lists B as peer, and B lists A and C,\n"
        "  then the chain is: A \xe2\x86\x94 B \xe2\x86\x94 C\n");
  } else {
    static constexpr char truncated[] = "\n[Topology output truncated]\n";
    const size_t suffixLen = sizeof(truncated) - 1;
    const size_t offset = TOPO_OUTPUT_CAPACITY - suffixLen - 1;
    memcpy(gTopoOutputBuffer + offset, truncated, suffixLen + 1);
  }

  // Note: result is returned via gTopoOutputBuffer to the HTTP caller.
  // No broadcastOutput here — avoids serial spam when the web UI polls repeatedly.
  return gTopoOutputBuffer;
}

// ============================================================================
// ESP-NOW Test Commands
// ============================================================================

// Test stream management
const char* cmd_test_streams(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  TopoStreamsGuard guard("cmd_test_streams");
  if (gTopoStreamsMutex && !guard.held) return "Error: topology state busy";
  memset(gTopoStreams, 0, sizeof(gTopoStreams));

  broadcastOutput("\n=== Testing Stream Management ===");
  
  uint8_t fakeMac1[6] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x01};
  uint8_t fakeMac2[6] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x02};
  uint8_t fakeMac3[6] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x03};
  
  BROADCAST_PRINTF("Creating stream 1 (MAC: aa:bb:cc:dd:ee:01, reqId: 100)");
  TopologyStream* s1 = findOrCreateTopoStreamLocked(fakeMac1, 100);
  BROADCAST_PRINTF("  Result: %p, active=%d", s1, s1 ? s1->active : 0);
  
  BROADCAST_PRINTF("Creating stream 2 (MAC: aa:bb:cc:dd:ee:02, reqId: 200)");
  TopologyStream* s2 = findOrCreateTopoStreamLocked(fakeMac2, 200);
  BROADCAST_PRINTF("  Result: %p, active=%d", s2, s2 ? s2->active : 0);
  
  BROADCAST_PRINTF("Creating stream 3 (MAC: aa:bb:cc:dd:ee:03, reqId: 300)");
  TopologyStream* s3 = findOrCreateTopoStreamLocked(fakeMac3, 300);
  BROADCAST_PRINTF("  Result: %p, active=%d", s3, s3 ? s3->active : 0);
  
  BROADCAST_PRINTF("\nTesting findTopoStream for stream 1:");
  TopologyStream* s1_again = findTopoStreamLocked(fakeMac1, 100);
  BROADCAST_PRINTF("  Found same pointer: %s", s1 == s1_again ? "YES" : "NO");
  
  BROADCAST_PRINTF("\nTesting findTopoStream for non-existent stream:");
  TopologyStream* s_none = findTopoStreamLocked(fakeMac1, 999);
  BROADCAST_PRINTF("  Result: %s", s_none ? "FOUND (ERROR!)" : "NULL (correct)");
  
  broadcastOutput("\nActive streams:");
  int activeCount = 0;
  for (int i = 0; i < MAX_CONCURRENT_TOPO_STREAMS; i++) {
    if (gTopoStreams[i].active) {
      activeCount++;
      BROADCAST_PRINTF("  Slot %d: reqId=%lu, MAC=%s", 
                      i, (unsigned long)gTopoStreams[i].reqId,
                      MAC_STR(gTopoStreams[i].senderMac));
    }
  }
  BROADCAST_PRINTF("Total active streams: %d/%d", activeCount, MAX_CONCURRENT_TOPO_STREAMS);
  
  broadcastOutput("\n=== Test Complete ===");
  return "OK";
}

