// Buffered ESP-NOW message history as JSON. This is what lets a BLE/CLI client
// retrieve the ASYNC results of relayed remote ops (espnowremote/browse/fetch) —
// otherwise those only reach the web's /api/espnow/messages poll, which a BLE
// app cannot hit. Mirrors that endpoint's per-message shape.
//   Usage: espnowmessages json [sinceSeq] [mac]
// sinceSeq pages incrementally (return only messages newer than that seq); mac
// filters to one peer. Same access level as espnowremote (the producer).
const char* cmd_espnow_messages(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  CommandArgs a(argsInput);

  uint32_t since = 0;
  uint8_t  mac[6];
  bool     hasMac = false;
  for (int i = 0; i < a.count(); i++) {
    const String& t = a.arg(i);
    if (t.equalsIgnoreCase("json")) continue;
    if (parseMacAddress(t, mac)) {                       // looks like a MAC
      hasMac = true;
      continue;
    }
    // Anything else has to be a sequence number: a mistyped MAC read as 0
    // would return every peer's messages.
    uint32_t seq = 0;
    if (!parseIntArg(t, seq)) {
      return argWantsJson(argsInput)
          ? "{\"schema\":1,\"ok\":false,\"error\":\"bad argument\"}"
          : "Error: Not a sequence number or MAC address. "
            "Usage: espnowmessages [json] [<sinceSeq>] [<AA:BB:CC:DD:EE:FF>]";
    }
    since = seq;
  }

  // Page size capped at 8: keeps the serialized JSON comfortably under the 4096-byte async
  // command-result buffer (ExecReq.out) so a page is never truncated into invalid JSON, and
  // keeps the BLE fragment count per page low so the paced send stays quick and reliable.
  // memreport (the largest/burstiest producer) is the worst case and fits within this.
  const int MAXM = 8;
  static ReceivedTextMessage* msgs = nullptr;
  if (!msgs) msgs = (ReceivedTextMessage*)ps_alloc(sizeof(ReceivedTextMessage) * MAXM,
                                                   AllocPref::PreferPsram, "espnow.msgs.cli");
  if (!msgs) return argWantsJson(argsInput) ? "{\"schema\":1,\"ok\":false,\"error\":\"oom\"}" : kCommandReplyOutOfMemory;
  int n = hasMac ? getPeerMessages(mac, msgs, MAXM, since)
                 : getAllMessages(msgs, MAXM, since);

  // Names are looked up now (the history keeps none), after the store lock,
  // once per distinct peer of this page: sent rows "" , unattributed rows the
  // MAC text, the rest the peer's current name.
  char names[MAXM][ESPNOW_HISTORY_NAME_CAP];
  espnowHistoryPageNames(msgs, n, names);

  if (argWantsJson(argsInput)) {
    PSRAM_JSON_DOC(doc);
    doc["schema"] = 1;
    JsonArray arr = doc["messages"].to<JsonArray>();
    for (int i = 0; i < n; i++) {
      JsonObject o = arr.add<JsonObject>();
      char macStr[18];
      macToDisplay(msgs[i].peerMac, macStr, sizeof(macStr));
      o["seq"]   = (unsigned long)msgs[i].seqNum;
      o["reqId"] = (unsigned long)msgs[i].reqId;
      o["piece"] = msgs[i].piece;
      o["of"]    = msgs[i].pieceTotal;
      o["mac"]  = String(macStr);
      o["name"] = (const char*)names[i];  // copied by ArduinoJson 7
      o["msg"]  = msgs[i].message;
      o["enc"]  = msgs[i].encrypted;
      o["ts"]   = (unsigned long)msgs[i].timestamp;
      o["type"] = (int)msgs[i].msgType;
      o["sent"] = msgs[i].isSent;          // direction: true = we sent it, false = received
      o["sendState"] = msgs[i].sendState;  // sent rows: 0 pending,1 delivered,2 timeout,3 failed
    }
    static char* jbuf = nullptr;
    if (!jbuf) jbuf = (char*)ps_alloc(32768, AllocPref::PreferPsram, "espnow.messages.json");
    if (!jbuf) return "{\"schema\":1,\"ok\":false,\"error\":\"oom\"}";
    serializeJson(doc, jbuf, 32768);
    return jbuf;
  }

  // Human text fallback (serial console).
  if (n == 0) return "No ESP-NOW messages";
  for (int i = 0; i < n; i++) {
    char macStr[18];
    macToDisplay(msgs[i].peerMac, macStr, sizeof(macStr));
    BROADCAST_PRINTF("[#%lu] %s%s: %s",
                     (unsigned long)msgs[i].seqNum,
                     names[i][0] ? names[i] : macStr,
                     msgs[i].encrypted ? " [enc]" : "",
                     msgs[i].message);
  }
  return "OK";
}

// WPS-style pairing mode: open a timed window on BOTH same-mesh devices and they
// auto secure-pair. Requires a mesh passphrase (encryption). Runtime-only.
// List devices discovered during the current discovery window (populated by
// v4h_pair_beacon). 'espnowdiscovered clear' flushes the list. The pair action
// is the existing 'espnowpairsecure <mac> <name>' built from a listed row.
const char* cmd_espnow_discovered(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  if (!gEspNow || !gEspNow->initialized) {
    return "Error: ESP-NOW not initialized. Run 'openespnow' first.";
  }
  CommandArgs a(argsInput);
  String sub = a.count() > 0 ? a.arg(0) : "";
  sub.toLowerCase();
  if (sub == "clear") {
    clearCandidates();
    return "Discovered candidate list cleared.";
  }

  uint32_t now = (uint32_t)millis();
  pruneStaleCandidates(now);
  if (!ensureDebugBuffer()) return "Error: Debug buffer unavailable";
  char* p = getDebugBuffer();
  const int cap = GLOBAL_DEBUG_BUFFER_SIZE;

  if (gEspNow->unpairedDeviceCount == 0) {
    snprintf(p, cap,
             "No devices discovered.%s Open discovery on BOTH devices with 'espnowpairmode', wait a few seconds.",
             espnowPairModeActive() ? "" : " (Your discovery window is CLOSED — run 'espnowpairmode' first.)");
    return p;
  }

  int n = snprintf(p, cap,
                   "Discovered (%d) — pair with 'espnowpairsecure <mac> <name>':\n",
                   gEspNow->unpairedDeviceCount);
  for (int i = 0; i < gEspNow->unpairedDeviceCount && n < cap - 96; i++) {
    UnpairedDevice& d = gEspNow->unpairedDevices[i];
    char macStr[18];
    macToDisplay(d.mac, macStr, sizeof(macStr));
    n += snprintf(p + n, cap - n, "  %s  %s  rssi=%d  age=%lus\n",
                  macStr, d.name.c_str(), d.rssi,
                  (unsigned long)((now - d.lastSeenMs) / 1000));
  }
  return p;
}

// Initiator: request a pair with a discovered device. Sends PAIR_REQUEST and
// waits for the target's Accept/Reject (the target must have discovery open).
const char* cmd_espnow_pairrequest(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  if (!gEspNow || !gEspNow->initialized) return "Error: ESP-NOW not initialized. Run 'openespnow' first.";
  if (!gEspNow->encryptionEnabled) return "Error: Set a mesh passphrase first (espnowsetpassphrase).";
  CommandArgs a(argsInput);
  if (!a.hasMinArgs(1)) return "Error: Usage: espnowpairrequest <mac_or_name>  (name/MAC from 'espnowdiscovered')";
  String target = a.arg(0);

  uint32_t now = (uint32_t)millis();
  pruneStaleCandidates(now);
  uint8_t tmpMac[6];
  bool haveMac = parseMacAddress(target, tmpMac);
  int found = -1;
  for (int i = 0; i < gEspNow->unpairedDeviceCount; i++) {
    if ((haveMac && memcmp(gEspNow->unpairedDevices[i].mac, tmpMac, 6) == 0) ||
        (!haveMac && gEspNow->unpairedDevices[i].name.equalsIgnoreCase(target))) {
      if (found >= 0) {
        // Two candidates share the name (two devices with one name, or two
        // "peer-B2C3" labels from the same last two address bytes): only the
        // MAC tells them apart.
        return "Error: more than one discovered device has that name. Use its MAC from 'espnowdiscovered'.";
      }
      found = i;
      if (haveMac) break;
    }
  }
  uint8_t mac[6];
  char name[devicename::kFieldLen];
  name[0] = '\0';
  if (found >= 0) {
    memcpy(mac, gEspNow->unpairedDevices[found].mac, 6);
    // Candidates hold a name already read by the rule (or "peer-B2C3").
    const char* cand = gEspNow->unpairedDevices[found].name.c_str();
    if (devicename::valid(cand)) snprintf(name, sizeof(name), "%s", cand);
  } else if (haveMac) {
    memcpy(mac, tmpMac, 6);
  } else {
    return "Error: not in the discovered list. Run 'espnowdiscovered' (both devices need discovery open).";
  }
  if (name[0] == '\0') devicename::formatWithMacSuffix(devicename::kPeerPrefix, mac, name);
  if (!ensureDebugBuffer()) return kCommandReplyOutOfMemory;

  // Pending first, so an answer to this first copy finds it; the heartbeat
  // sweep re-sends it until answered (PairCore).
  portENTER_CRITICAL(&gPairLock);
  espnowpair::startRequest(gPair, mac, name, now);
  portEXIT_CRITICAL(&gPairLock);
  sendPairCtrl(mac, ESPNOW_V4_TYPE_PAIR_REQUEST);

  snprintf(getDebugBuffer(), GLOBAL_DEBUG_BUFFER_SIZE,
           "Pair request sent to '%s'. Waiting for them to Accept (they need discovery open)...", name);
  return getDebugBuffer();
}

// Shared arg-match for accept/reject against the single pending incoming request.
static bool pendingInMatchesArg(const String& argsInput, const espnowpair::Request& in) {
  CommandArgs a(argsInput);
  if (a.count() == 0) return true;  // no arg → the sole pending request
  String t = a.arg(0);
  uint8_t m[6];
  if (parseMacAddress(t, m)) return macEquals(m, in.mac);
  return t.equalsIgnoreCase(in.name);
}

// Take the pending incoming request as answered (accept/reject). Returns the
// command's error text, or nullptr with `taken` filled. The answer is
// remembered, so a repeat of the request gets it again (PairCore).
static const char* takePendingIn(const String& argsInput, espnowpair::Answer answer,
                                 const char* noneText, espnowpair::Request& taken) {
  portENTER_CRITICAL(&gPairLock);
  const espnowpair::Request in = gPair.in;
  portEXIT_CRITICAL(&gPairLock);
  if (!in.active) return noneText;
  if (!pendingInMatchesArg(argsInput, in)) return "Error: that name/MAC doesn't match the pending request.";
  portENTER_CRITICAL(&gPairLock);
  // Answer the request that was matched, not a newer one that replaced it meanwhile.
  const bool same = gPair.in.active && gPair.in.atMs == in.atMs && macEquals(gPair.in.mac, in.mac);
  const bool took = same && espnowpair::answerIncoming(gPair, answer, (uint32_t)millis(), &taken);
  portEXIT_CRITICAL(&gPairLock);
  return took ? nullptr : "Error: the pending request changed; check 'espnowpairmode status'.";
}

// Target: accept the pending incoming request. Tells the initiator, then pairs
// locally (cmd_espnow_pairsecure writes OUR registry + drives KEY_EX).
const char* cmd_espnow_accept(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  if (!gEspNow || !gEspNow->initialized) return "Error: ESP-NOW not initialized.";
  // What the local pairing below is known to refuse (no encryption, a full
  // device table) is refused before the request is answered, so no Accept is
  // recorded or sent for a pairing that cannot follow. The other side pairs
  // when it gets the Accept. A refusal that only shows while pairing (the
  // radio does not take the peer) still comes after the Accept; the reply
  // below says so.
  if (!gEspNow->encryptionEnabled) {
    return "Error: Encryption not enabled. Run 'espnowsetpassphrase <mesh> <passphrase>' first.";
  }
  if (!ensureDebugBuffer()) return kCommandReplyOutOfMemory;
  {
    portENTER_CRITICAL(&gPairLock);
    const espnowpair::Request pending = gPair.in;
    portEXIT_CRITICAL(&gPairLock);
    if (pending.active && pendingInMatchesArg(argsInput, pending) && gEspNow->deviceCount >= 16) {
      // A requester that is already in the table is updated in place and
      // needs no free slot.
      bool inTable = false;
      for (int i = 0; i < gEspNow->deviceCount && !inTable; i++) {
        inTable = macEquals(gEspNow->devices[i].mac, pending.mac);
      }
      if (!inTable) {
        return "Error: Maximum number of devices (16) already paired. Unpair one with "
               "'espnowunpair <name_or_mac>', then run 'espnowaccept' again.";
      }
    }
  }
  espnowpair::Request req = {};
  const char* err = takePendingIn(argsInput, espnowpair::Answer::Accept,
                                  "Error: No pending pair request. Open discovery with 'espnowpairmode' "
                                  "on both devices and send the request again.", req);
  if (err) return err;

  sendPairCtrl(req.mac, ESPNOW_V4_TYPE_PAIR_ACCEPT);   // re-sent by the heartbeat sweep (PairCore)
  char macStr[18]; macToDisplay(req.mac, macStr, sizeof(macStr));
  String pairArgs = String(macStr) + " " + req.name;
  String resCopy = cmd_espnow_pairsecure(pairArgs);  // copy: pairsecure may reuse the debug buffer
  if (commandReplyIsFailure(resCopy.c_str())) {
    // The other side was already told Accept, and the local pairing answered
    // with an error. That is not always "did not pair": with a device list
    // that could not be saved the device is paired for this session. The lead
    // says only what is true in both cases and the pairing's own text follows.
    snprintf(getDebugBuffer(), GLOBAL_DEBUG_BUFFER_SIZE,
             "Error: Accepted '%s', but the pairing on this device reported: %s",
             req.name, commandReplyReason(resCopy.c_str()));
    return getDebugBuffer();
  }
  snprintf(getDebugBuffer(), GLOBAL_DEBUG_BUFFER_SIZE, "Accepted '%s'. %s", req.name, resCopy.c_str());
  return getDebugBuffer();
}

// Target: reject the pending incoming request.
const char* cmd_espnow_reject(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  if (!gEspNow || !gEspNow->initialized) return "Error: ESP-NOW not initialized.";
  if (!ensureDebugBuffer()) return kCommandReplyOutOfMemory;
  espnowpair::Request req = {};
  const char* err = takePendingIn(argsInput, espnowpair::Answer::Reject,
                                  "Error: No pending pair request. Nothing to reject.", req);
  if (err) return err;
  sendPairCtrl(req.mac, ESPNOW_V4_TYPE_PAIR_REJECT);

  snprintf(getDebugBuffer(), GLOBAL_DEBUG_BUFFER_SIZE, "Rejected pair request from '%s'.", req.name);
  return getDebugBuffer();
}

const char* cmd_espnow_pairmode(const String& argsInput) {
  RETURN_VALID_IF_VALIDATE_CSTR();
  if (!gEspNow || !gEspNow->initialized) {
    return "Error: ESP-NOW not initialized. Run 'openespnow' first.";
  }
  CommandArgs a(argsInput);
  String sub = a.count() > 0 ? a.arg(0) : "";
  sub.toLowerCase();

  if (argIsOff(sub) || sub == "stop") {
    const bool wasOpen = espnowPairModeActive();
    espnowPairModeClose();  // also drops candidates left by a window that expired
    if (!wasOpen) {
      return "Error: Discovery is not running. Open it with 'espnowpairmode [seconds]'.";
    }
    return "Pairing mode off.";
  }
  if (sub == "status") {
    if (!ensureDebugBuffer()) return "Error: Debug buffer unavailable";
    char* p = getDebugBuffer();
    int n;
    if (espnowPairModeActive()) {
      n = snprintf(p, GLOBAL_DEBUG_BUFFER_SIZE,
                   "Discovery ON (%lus left). Radio channel: %u.",
                   (unsigned long)(espnowPairModeRemainingMs() / 1000),
                   (unsigned)gEspNow->channel);
    } else {
      n = snprintf(p, GLOBAL_DEBUG_BUFFER_SIZE,
                   "Discovery off. Radio channel: %u.", (unsigned)gEspNow->channel);
    }
    portENTER_CRITICAL(&gPairLock);
    const espnowpair::Request in = gPair.in, out = gPair.out;
    portEXIT_CRITICAL(&gPairLock);
    if (in.active) {
      n += snprintf(p + n, GLOBAL_DEBUG_BUFFER_SIZE - n,
                    "\nIncoming request from '%s' — 'espnowaccept' or 'espnowreject'.", in.name);
    }
    if (out.active) {
      n += snprintf(p + n, GLOBAL_DEBUG_BUFFER_SIZE - n,
                    "\nWaiting on '%s' to accept our request.", out.name);
    }
    return p;
  }

  // Open the window. Pairing rides KEY_EX (mesh-passphrase HMAC), so a passphrase
  // must already be set — refuse early with an actionable message otherwise.
  if (!gEspNow->encryptionEnabled) {
    return "Error: Set a mesh passphrase first (espnowsetpassphrase). Pairing needs the shared mesh key.";
  }
  // A number is the duration; an on word opens the window for the default time.
  uint32_t secs = 120;
  if (sub.length() > 0 && !parseIntArg(sub, 1, 600, secs) && !argIsOn(sub)) {
    return "Error: Duration must be 1 to 600 seconds. Use 'espnowpairmode off' to close the window.";
  }
  if (!ensureDebugBuffer()) return kCommandReplyOutOfMemory;
  espnowPairModeOpen(secs);
  snprintf(getDebugBuffer(), GLOBAL_DEBUG_BUFFER_SIZE,
           "Discovery ON for %lus on channel %u. Open discovery on the other device too "
           "(same mesh, same channel), then run 'espnowdiscovered' to see it and pair. "
           "Devices no longer auto-pair.",
           (unsigned long)secs, (unsigned)gEspNow->channel);
  return getDebugBuffer();
}

